package com.gameaggregator.versionservice.domain;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity @Table(name="game_versions",uniqueConstraints=@UniqueConstraint(columnNames={"gameId","semanticVersion"})) public class GameVersion{@Id public UUID id=UUID.randomUUID();@Column(nullable=false)public UUID gameId;@Column(nullable=false,length=64)public String semanticVersion;@Column(nullable=false)public String status="DRAFT";@Lob @Column(nullable=false)public String changelog;@Lob @Column(nullable=false)public String compatibilityJson;@Lob @Column(nullable=false)public String supportedPlatformsJson;public String minimumClientVersion;@Column(nullable=false)public Instant createdAt=Instant.now();@Version public long revision;protected GameVersion(){}public GameVersion(UUID g,String v,String c,String x,String p,String m){gameId=g;semanticVersion=v;changelog=c;compatibilityJson=x;supportedPlatformsJson=p;minimumClientVersion=m;}}